<script lang="ts">
 import {languageOverrides} from "./localization";
 import {printDocument} from "./print-dialog";
 import type {Project} from './model';import {registerTable,registerRowInRange} from './register-data';import {matchesRegisterFilters,openRegisterFilter,type RegisterFilter} from './register-filter';import {translator} from './i18n';import {displayDate} from './date-format';import {escapeMarkup} from './report-exports';import {tableXLSX} from './xlsx';import {csv} from './engine';import {native,exportPDF,exportBinary,exportText} from './storage';import {Printer,Download,Search,X,ChevronLeft,ChevronRight,ArrowDownUp,Filter,RefreshCw} from '@lucide/svelte';
 export let project:Project;export let kind:string;export let title:string;export let parentId:string;
 let from='',to='',accountId='',query='',attentionOnly=false,column=0,descending=false,page=1,error='',revision=0,selected=-1,filters:RegisterFilter[]=[];
 $:t=translator(project.settings.language,$languageOverrides);$:data=refreshed(project,kind,revision);
 $:filtered=data.rows.filter(row=>matchesRegisterFilters(row.filterValues||[row.date,...row.values.slice(1)],filters)&&registerRowInRange(row,from,to)&&(!accountId||row.accountId===accountId)&&(!attentionOnly||row.attention)&&row.values.join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase())).sort((a,b)=>{const result=data.dateColumns?.includes(column)?(a.filterValues?.[column]||(column===0?a.date:a.values[column])||'').localeCompare(b.filterValues?.[column]||(column===0?b.date:b.values[column])||''):column>=data.numericStart&&column<data.numericStart+data.numericCount?Number(a.values[column])-Number(b.values[column]):(a.values[column]||'').localeCompare(b.values[column]||'',undefined,{numeric:true});return descending?-result:result;});
 $:signature=JSON.stringify([from,to,accountId,query,attentionOnly,column,descending,filters]);$:if(signature)page=1;
 $:pages=Math.max(1,Math.ceil(filtered.length/100));$:page=Math.min(page,pages);
 function html(rows:typeof filtered){const esc=escapeMarkup;return '<!doctype html><html lang="'+project.settings.language+'"><head><meta charset="utf-8"><style>body{font:12px Arial,sans-serif;color:#17191d;background:white;margin:20px}h1{font-size:18px}table{border-collapse:collapse;width:100%}th,td{padding:7px;border:1px solid #c7cdd3;text-align:left;overflow-wrap:anywhere}th{font-weight:bold;background:#e7edf3;position:sticky;top:0}.attention{background:#fff2da}thead{display:table-header-group}tr{break-inside:avoid}@media print{@page{size:A4 landscape;margin:12mm}th{position:static}body{margin:0}}</style></head><body><h1>'+esc(title)+'</h1><p>'+esc(project.organization.name)+' · '+esc(from?displayDate(from,project):t('Начало истории','Începutul istoricului'))+'–'+esc(to?displayDate(to,project):t('Без ограничения','Fără limită'))+'</p><p>'+esc(t('Записей: ','Înregistrări: '))+filtered.length+'</p><table><thead><tr>'+data.headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr'+(row.attention?' class="attention"':'')+'>'+row.values.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></body></html>';}
 function configureFilter(){const defaults=data.headers.map((_,column)=>({column,enabled:false,comparison:'eq' as const,values:[]}));openRegisterFilter({id:parentId,parentId,labels:data.headers,dateColumns:data.dateColumns||[0],items:data.headers.map((_,i)=>[...new Set(data.rows.map(r=>(r.filterValues||[r.date,...r.values.slice(1)])[i]).filter(Boolean))].sort()),filters:filters.length?filters:defaults,onapply:next=>filters=next});}
 function refreshed(p:Project,view:string,_revision:number){return registerTable(p,view);}
 function sort(i:number){if(column===i)descending=!descending;else {column=i;descending=false;}}

 async function download(type:string){try{const name='OpenHaU-'+kind+'-'+(from||'all')+'-'+(to||'all');if(type==='pdf')await exportPDF(name+'.pdf',html(filtered),true);else if(type==='xlsx')await exportBinary(name+'.xlsx',tableXLSX(title,project.organization.name+' · '+from+'–'+to,data.headers,filtered.map(r=>r.values),data.numericStart,data.numericCount,{totalLastRow:false,numberFormat:data.numberFormat}),'xlsx');else await exportText(name+'.csv',csv([data.headers,...filtered.map(r=>r.values)]),'csv');error='';}catch(e){error=e instanceof Error?e.message:String(e);}}
 function print(){void printDocument(html(filtered),true);}
</script>
<div class="data-register">
<div class="register-toolbar"><button class="tool" title={t('Обновить','Actualizează')} onclick={()=>revision++}><RefreshCw size={17}/></button><button class="tool" title={t('Отбор','Filtrare')} onclick={configureFilter}><Filter size={17}/></button><button class="tool" title={t('Снять отбор','Resetează filtrul')} onclick={()=>{filters=[];query='';attentionOnly=false;from='';to='';accountId='';}}><X size={17}/></button><span class="spacer"></span><button class="tool" onclick={print} disabled={!filtered.length}><Printer size={16}/>{t('Печать','Imprimare')}</button><button class="tool" onclick={()=>download('pdf')} disabled={!native||!filtered.length}><Download size={16}/>PDF</button><button class="tool" onclick={()=>download('xlsx')} disabled={!filtered.length}><Download size={16}/>XLSX</button><button class="tool" onclick={()=>download('csv')} disabled={!filtered.length}><Download size={16}/>CSV</button></div>
<div class="register-toolbar"><label class="query"><Search size={16}/><input aria-label={t('Поиск в регистре','Caută în registru')} placeholder={t('Поиск','Căutare')} bind:value={query}/></label><label class="check-row"><input type="checkbox" bind:checked={attentionOnly}/>{t('Требует внимания','Necesită atenție')}</label></div>
{#if error}<p class="alert error" role="alert">{error}</p>{/if}
<div class="register-grid"><table><thead><tr>{#each data.headers as header,i}<th><button onclick={()=>sort(i)}>{header}{#if column===i}<ArrowDownUp size={13}/>{/if}</button></th>{/each}</tr></thead><tbody>{#each filtered.slice((page-1)*100,page*100) as row,i}<tr class:attention={row.attention} class:selected={selected===(page-1)*100+i}>{#each row.values as value}<td><button onclick={()=>selected=(page-1)*100+i}>{value||' '}</button></td>{/each}</tr>{/each}</tbody></table>{#if !filtered.length}<p class="empty-register">{t('По выбранному отбору записей нет.','Nu sunt înregistrări pentru filtrul selectat.')}</p>{/if}</div>
<div class="register-pages"><span>{t('Записей: ','Înregistrări: ')}{filtered.length}</span><button aria-label={t('Предыдущая страница','Pagina precedentă')} disabled={page===1} onclick={()=>page--}><ChevronLeft size={16}/></button><span>{page} / {pages}</span><button aria-label={t('Следующая страница','Pagina următoare')} disabled={page===pages} onclick={()=>page++}><ChevronRight size={16}/></button></div>
{#if kind==='tariffs'}<p class="register-note">{t('Пустые поля вида тарифа и тарифа сверх означают, что эти значения не сохранены в базе.','Câmpurile goale pentru tipul tarifului și tariful suplimentar indică valori care nu sunt păstrate în bază.')}</p>{/if}
{#if kind==='charges'||kind==='service-volume'}<p class="register-note">{t('Показаны месячные итоги сохранённых начислений.','Sunt afișate totalurile lunare ale calculelor păstrate.')}</p>{/if}</div>
<style>.data-register{padding:8px;display:flex;flex-direction:column;gap:8px;min-height:100%;box-sizing:border-box}.register-toolbar{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.tool{display:flex;gap:6px;align-items:center;background:transparent;border:0;color:var(--text);padding:7px 9px;min-height:34px}.tool:hover{background:var(--hover)}.spacer{flex:1}.query{display:flex;gap:6px;align-items:center}.query input{height:32px;box-sizing:border-box}.register-grid{overflow:auto;flex:1;min-height:220px;max-height:65vh}table{border-collapse:collapse;width:100%;font-size:12px}th{position:sticky;top:0;background:var(--surface);z-index:1;text-align:left}td,th{border:1px solid var(--border)}th button,td button{font:inherit;color:inherit;border:0;background:transparent;display:flex;align-items:center;gap:6px;min-width:100%;text-align:left;padding:6px 9px;white-space:nowrap}th button{font-weight:600}tr.attention{background:#ba88251c}tr.selected{background:var(--accent);color:white}.register-pages{display:flex;align-items:center;gap:12px}.register-pages button{display:flex;padding:5px;background:transparent;border:0;color:var(--text)}.register-note{font-size:11px;color:var(--muted);margin:0}.empty-register{padding:24px;color:var(--muted)}</style>
